settings.custom_liquid:
{% liquid
  assign mobile = images['hoodie-tara.webp']
  assign desktop = images['hoodie-frano.webp']
  assign english = false
  if request.locale.iso_code == 'en'
    assign english = true
  endif
%}
{% if collection.handle == 'hundesport-t-shirts-hoodies' %}
{% if mobile != blank and desktop != blank %}
<section class="iq-hoodie-hero" aria-labelledby="iq-hoodie-title">
  <picture>
    <source media="(max-width:749px)" srcset="{{ mobile | image_url: width: 600 }} 600w, {{ mobile | image_url: width: 900 }} 900w, {{ mobile | image_url: width: 1200 }} 1200w, {{ mobile | image_url: width: 1600 }} 1600w" sizes="100vw" width="{{ mobile.width }}" height="{{ mobile.height }}">
    {{ desktop | image_url: width: 2160 | image_tag: widths: '960,1280,1600,1920,2160', sizes: '100vw', loading: 'eager', fetchpriority: 'high', alt: '' }}
  </picture>
  <div class="iq-hoodie-copy">
    <span class="iq-hoodie-label">HOODIES &amp; T-SHIRTS</span>
    <h1 id="iq-hoodie-title">{% if english %}Your everyday.<span>With your dog.</span>{% else %}Dein Alltag.<span>Mit Hund.</span>{% endif %}</h1>
    <p>{% if english %}Hoodies &amp; T-shirts with room for more.<br>For everything you want to bring along with your dog.{% else %}Hoodies &amp; T-Shirts mit Platz für mehr.<br>Für alles, was Du mit Deinem Hund dabeihaben willst.{% endif %}</p>
  </div>
</section>
{% elsif request.design_mode %}
<p>Bannerbilder fehlen: Bitte hoodie-tara.webp und hoodie-frano.webp unter Inhalte → Dateien prüfen.</p>
{% endif %}
<style>
.iq-hoodie-hero,.iq-hoodie-hero *{box-sizing:border-box}
.iq-hoodie-hero{position:relative;isolation:isolate;overflow:hidden}.iq-hoodie-hero picture,.iq-hoodie-hero img{display:block;width:100%}.iq-hoodie-hero img{height:auto}.iq-hoodie-copy{position:absolute;left:5%;top:33%;width:30%;z-index:2}.iq-hoodie-copy h1{font:italic 800 clamp(28px,3.3vw,64px)/1.04 Montserrat,sans-serif;text-transform:uppercase;letter-spacing:-.035em;margin:0 0 18px;color:white;text-shadow:0 2px 8px #17171766}.iq-hoodie-copy h1 span{display:block;color:#A51D1B;text-shadow:0 1px 1px #ffffff33}.iq-hoodie-copy p{font:400 16px/1.5 Archivo,sans-serif;color:white;text-shadow:0 1px 4px #171717;margin:0;max-width:320px}.iq-hoodie-label{font:400 12px/1.4 Archivo,sans-serif;color:white;display:block;margin-bottom:12px;letter-spacing:.06em}.iq-hoodie-hero:after{content:'';position:absolute;inset:0;pointer-events:none;background:linear-gradient(90deg,#17171750,transparent 42%);z-index:1}@media(max-width:749px){.iq-hoodie-hero{aspect-ratio:4/5}.iq-hoodie-hero picture,.iq-hoodie-hero img{height:100%;width:100%}.iq-hoodie-hero img{object-fit:cover;object-position:49% center}.iq-hoodie-copy{left:6%;right:6%;width:auto;top:auto;bottom:5%}.iq-hoodie-copy h1{font-size:clamp(29px,8vw,48px);text-align:center;margin-bottom:14px}.iq-hoodie-label{text-align:center;font-size:11px;margin-bottom:9px}.iq-hoodie-copy p{font-size:14px;line-height:1.45;max-width:none}.iq-hoodie-hero:after{background:linear-gradient(0deg,#171717b3 0%,#17171765 25%,transparent 52%)}}@media(max-width:749px){.iq-hoodie-copy h1 span{color:#A51D1B;text-shadow:0 1px 1px #ffffff33}}

.iq-hoodie-copy .mobile-copy{display:none}@media(max-width:749px){.iq-hoodie-copy .desktop-copy{display:none}.iq-hoodie-copy .mobile-copy{display:block}.iq-hoodie-copy .mobile-copy span{display:block}}

</style>
{% endif %}

{% if collection.description != blank %}
  <div style="padding:12px 20px 0;">
    <div style="max-width:1180px;margin:0 auto;text-align:center;font-size:18px;line-height:1.5;color:#222;">
      {{ collection.description | replace: '<p>', '<p style="margin:0;">' }}
    </div>
  </div>
{% endif %}

{%- liquid
  assign iq_en = false
  if request.locale.iso_code == 'en'
    assign iq_en = true
  endif
  assign iq_photo = images['iq-04-performance-tshirt.webp']
  if iq_en
    assign iq_alt = 'Man taking a blue toy from the back pocket of his IQ Performance T-Shirt'
  else
    assign iq_alt = 'Mann zieht ein blaues Spielzeug aus der Rückentasche seines IQ Performance T-Shirts'
  endif
-%}
<section class="iq-hs-4">
<div class="copy">{% if iq_en %}<p class="kicker">IQ Performance T-Shirt · Women & Unisex</p><h2 class="title">Thoughtful fabric.<br><span>Rewards within reach.</span></h2><p>Two-layer double-face fabric: cotton jersey outside, polyester mesh inside. Plus a zipped back pocket for toys – on the IQ Performance T-Shirt in women’s and unisex fits.</p>{% else %}<p class="kicker">IQ Performance T-Shirt · Damen & Unisex</p><h2 class="title">Durchdachter Stoff.<br><span>Belohnung griffbereit.</span></h2><p>Zweilagiger Double-Face-Stoff: Baumwolljersey außen, Polyester-Mesh innen. Dazu eine Rückentasche mit Reißverschluss fürs Spielzeug – beim IQ Performance T-Shirt für Damen und Unisex.</p>{% endif %}</div>
<div class="photo">
{% if iq_photo != blank %}
{{ iq_photo | image_url: width: 1000 | image_tag: widths: '360, 480, 640, 800, 1000', sizes: '(min-width: 1200px) 600px, (min-width: 750px) 50vw, 100vw', loading: 'lazy', decoding: 'async', alt: iq_alt }}
{% endif %}
</div></section>
<style>.iq-hs-4{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);align-items:center;width:100%;max-width:1600px;min-width:0;gap:0;margin:24px auto;padding:0;box-sizing:border-box;background:transparent;color:#18191b}
.iq-hs-4 .copy{min-width:0;box-sizing:border-box;padding:28px clamp(20px,4vw,64px);overflow-wrap:anywhere}
.iq-hs-4 .kicker{font:700 11px/1.5 Archivo,Arial,sans-serif;letter-spacing:.1em;text-transform:uppercase;color:#a51d1b;margin:0 0 12px}
.iq-hs-4 .title{font-family:Montserrat,Arial,sans-serif;font-size:clamp(28px,3vw,42px);font-weight:800;font-style:italic;text-transform:uppercase;line-height:1.1;letter-spacing:-.03em;margin:0 0 16px}
.iq-hs-4 .title span{color:#a51d1b}
.iq-hs-4 .copy p:not(.kicker){font:400 15px/1.5 Archivo,Arial,sans-serif;margin:0;max-width:510px}
.iq-hs-4 .photo{min-width:0;width:100%;max-width:600px;justify-self:center}
.iq-hs-4 img{display:block;width:100%;height:auto;max-width:100%;border-radius:0}
.collection__content:has(.iq-hs-4)>.flex,#ProductGridContainer:has(.iq-hs-4),#ProductsList:has(.iq-hs-4),.collection-inline-block:has(.iq-hs-4){min-width:0;max-width:100%;box-sizing:border-box}
.collection-inline-block--full:has(.iq-hs-4){grid-column:1/-1;width:100%}
@media(max-width:749px){.iq-hs-4{display:flex;flex-direction:column;margin:20px 0;gap:0}.iq-hs-4 .photo{order:-1;max-width:none}.iq-hs-4 .copy{padding:18px 16px 22px;width:100%}.iq-hs-4 .title{font-size:26px;margin-bottom:12px}.iq-hs-4 .kicker{font-size:10px}.iq-hs-4 .copy p:not(.kicker){font-size:14px;line-height:1.5}}</style>

